/**
 * The text of the generated files. Nothing here reads the clock, the machine
 * or the commit: a commit in the text would change every target's key.
 *
 * @since 0.1.0
 */

import type { Inventory, Toolchain } from "../contract/Inventory.ts"
import type { GeneratedFile } from "../contract/Parts.ts"
import { markerDirectory, type StepPlan, type StepTarget } from "./Steps.ts"

/**
 * The file holding every generated target. It is the root package because a
 * glob sees only its own package, and a step can read any file. A directory
 * with its own `PACKAGE.ts` is another package, which the root glob skips.
 *
 * @category constants
 * @since 0.1.0
 */
export const packagePath = "PACKAGE.ts"

/**
 * The generated workspace declaration.
 *
 * @category constants
 * @since 0.1.0
 */
export const workspacePath = ".smithers/WORKSPACE.ts"

/**
 * The generated GitHub Actions workflow.
 *
 * @category constants
 * @since 0.1.0
 */
export const workflowPath = ".github/workflows/smithers-ci.yml"

const generated = "Generated by smithers-ci. Do not edit."

// GitHub stops a job after six hours; the build's own default is 30 minutes.
const stepTimeout = "6h"

const setupActions: ReadonlyMap<string, { readonly uses: string; readonly input: string }> = new Map([
  ["bun", { uses: "oven-sh/setup-bun@v2", input: "bun-version" }],
  ["go", { uses: "actions/setup-go@v5", input: "go-version" }],
  ["just", { uses: "extractions/setup-just@v3", input: "just-version" }],
  ["node", { uses: "actions/setup-node@v4", input: "node-version" }],
  ["pnpm", { uses: "pnpm/action-setup@v4", input: "version" }],
  ["python", { uses: "actions/setup-python@v5", input: "python-version" }],
  ["rust", { uses: "dtolnay/rust-toolchain@stable", input: "toolchain" }],
  ["zig", { uses: "mlugg/setup-zig@v2", input: "version" }]
])

const text = (value: string): string => JSON.stringify(value)

const comment = (value: string): string => `// ${value.replace(/[\r\n\u2028\u2029]+/g, " ")}`

const yamlComment = (value: string): string => `# ${value.replace(/[\r\n\u2028\u2029]+/g, " ")}`

const workspaceName = (repository: string): string => {
  const name = repository.replace(/[^A-Za-z0-9._-]+/g, "-").replace(/^[^A-Za-z0-9]+/, "")
  return name === "" ? "repository" : name
}

const renderWorkspace = (inventory: Inventory): string =>
  [
    comment(generated),
    `import { Smithers as S } from "@smthrs/targets"`,
    ``,
    `export const Workspace = S.Workspace(${text(workspaceName(inventory.repository))}, {`,
    `  repository: ${text(inventory.repository)},`,
    `  cache: S.Cache({ directory: ".flows" }),`,
    `  host: S.Host({ bins: ["sh"] })`,
    `})`,
    ``
  ].join("\n")

const renderTarget = (target: StepTarget, index: number, variables: ReadonlyMap<string, string>): string => {
  const data = ["repository", ...target.dependencies.map((label) => variables.get(label) as string)]
  const fields = [
    `shell: ${text(target.script)}`,
    ...(target.rule === "setup"
      ? [`outFiles: [${text(`//${markerDirectory}/${target.label}`)}]`, `cache: false`]
      : []),
    ...(Object.keys(target.env).length === 0 ? [] : [`env: ${JSON.stringify(target.env)}`]),
    ...(target.host === undefined ? [] : [`hosts: [${text(target.host)}]`]),
    `sandbox: "none"`,
    `timeout: ${text(stepTimeout)}`,
    `data: [${data.join(", ")}]`
  ]
  return [
    comment(target.title),
    `const step${index} = S.Shell.${target.rule === "setup" ? "Build" : "Test"}({`,
    fields.map((field) => `  ${field}`).join(",\n"),
    `})`,
    ``
  ].join("\n")
}

const renderPackage = (plan: StepPlan): string => {
  const variables = new Map(plan.targets.map((target, index) => [target.label, `step${index}`]))
  return [
    comment(generated),
    ...(plan.notes.length === 0 ? [] : [comment("Not reproduced from the original CI:"), ...plan.notes.map(comment)]),
    `import { Smithers as S } from "@smthrs/targets"`,
    ``,
    comment("A step can read any file, so every target declares the whole repository."),
    `const repository = S.glob("//**")`,
    ``,
    ...plan.targets.map((target, index) => renderTarget(target, index, variables)),
    `export const Package = S.Package({`,
    `  targets: {`,
    plan.targets.map((target, index) => `    ${text(target.label)}: step${index}`).join(",\n"),
    `  }`,
    `})`,
    ``
  ].join("\n")
}

const byNameThenSource = (left: Toolchain, right: Toolchain): number =>
  `${left.name}\n${left.source}` < `${right.name}\n${right.source}` ? -1 : 1

const renderSetup = (toolchain: Toolchain): ReadonlyArray<string> => {
  const action = setupActions.get(toolchain.name)
  if (action === undefined) {
    return [`      ${yamlComment(`${toolchain.name} (${toolchain.source}) has no known setup action.`)}`]
  }
  return [
    `      - uses: ${action.uses}`,
    ...(toolchain.version === undefined
      ? []
      : [`        with:`, `          ${action.input}: ${text(toolchain.version)}`])
  ]
}

const renderWorkflow = (inventory: Inventory, plan: StepPlan): string => {
  const toolchains = new Map<string, Toolchain>()
  for (const toolchain of [...inventory.toolchains].sort(byNameThenSource)) {
    if (!toolchains.has(toolchain.name)) toolchains.set(toolchain.name, toolchain)
  }
  const hasNode = toolchains.has("node")
  return [
    yamlComment(generated),
    `name: Smithers CI`,
    `on:`,
    ...plan.triggers.map((trigger) => `  ${trigger}:`),
    `permissions:`,
    `  contents: read`,
    `jobs:`,
    `  ci:`,
    `    strategy:`,
    `      fail-fast: false`,
    `      matrix:`,
    `        os: [${plan.runners.map(text).join(", ")}]`,
    `    runs-on: \${{ matrix.os }}`,
    `    steps:`,
    `      - uses: actions/checkout@v4`,
    ...(hasNode ? [] : [`      - uses: actions/setup-node@v4`, `        with:`, `          node-version: "24"`]),
    ...[...toolchains.values()].flatMap(renderSetup),
    `      ${yamlComment("Targets share one working tree, so they run one at a time.")}`,
    `      - run: npx --yes --package=@smthrs/cli@next smthrs ci '//...' --jobs 1`,
    ``
  ].join("\n")
}

/**
 * Renders the workspace, the targets and the workflow, sorted by path.
 *
 * @throws {never}
 * @category rendering
 * @since 0.1.0
 */
export const renderFiles = (inventory: Inventory, plan: StepPlan): ReadonlyArray<GeneratedFile> => [
  { path: workflowPath, content: renderWorkflow(inventory, plan) },
  { path: workspacePath, content: renderWorkspace(inventory) },
  { path: packagePath, content: renderPackage(plan) }
]
